          description:'The complete Kenya CBC Grade 8 English course: listening and speaking, reading, grammar in use and writing, taught strand by strand with original texts, step-by-step examples, interactive questions and quizzes.',
          longDescription:'This course follows the KICD Junior School Grade 8 English curriculum design, which teaches English through fifteen themes, from Human Rights and Scientific Innovations to Sports: Olympics and Tourist Attraction Sites in Africa. The course is organised strand by strand — Listening and Speaking, Reading, Grammar in Use and Writing — and each strand opens with an overview and its learning outcomes. Every sub-strand has three lessons followed by a quiz, an assignment, a revision page and a summary. Lessons include learning outcomes and objectives, a key inquiry question, a teacher explanation, vocabulary with pronunciation, language notes, original Kenyan texts, worked examples, all four language skills, grammar and communication focus, guided practice, independent, pair, group and digital activities, CBC competencies, values and PCIs, common mistakes, exam tips, homework, reflection, a glossary and a 10-question quiz with explanations.',
